// NumPy transcriptions: np.cumsum/np.cumprod and the array-api-aligned
// np.cumulative_sum/np.cumulative_prod (NumPy >= 2.1) share one test body
// upstream (parametrized); rstsr implements the array-api spellings.
mod numpy_cumulative {
    use super::*;
    static FUNC: &str = "numpy_cumulative";

    #[test]
    fn test_cumsum_basic() {
        // numpy: v2.5.2 | numpy/lib/tests/test_function_base.py::TestCumsum::test_basic (L748)
        crate::specify_test!("test_cumsum_basic");
        let mut device = TESTCFG.device.clone();
        device.set_default_order(RowMajor);

        // a = np.array([1, 2, 10, 11, 6, 5, 4])     (dtype loop N/A: rstsr checks dtypes at compile
        // time) assert_array_equal(cumsum(a, axis=0), np.array([1, 3, 13, 24, 30, 35, 39]))
        let a = rt::tensor_from_nested!([1, 2, 10, 11, 6, 5, 4], &device);
        let expected = rt::tensor_from_nested!([1, 3, 13, 24, 30, 35, 39], &device);
        assert_equal(rt::cumulative_sum(&a, 0), &expected, None);

        // a2 = np.array([[1, 2, 3, 4], [5, 6, 7, 9], [10, 3, 4, 5]])
        // assert_array_equal(cumsum(a2, axis=0), [[1, 2, 3, 4], [6, 8, 10, 13], [16, 11, 14, 18]])
        let a2 = rt::tensor_from_nested!([[1, 2, 3, 4], [5, 6, 7, 9], [10, 3, 4, 5]], &device);
        let expected = rt::tensor_from_nested!([[1, 2, 3, 4], [6, 8, 10, 13], [16, 11, 14, 18]], &device);
        assert_equal(rt::cumulative_sum(&a2, 0), &expected, None);

        // assert_array_equal(cumsum(a2, axis=1), [[1, 3, 6, 10], [5, 11, 18, 27], [10, 13, 17,
        // 22]])
        let expected = rt::tensor_from_nested!([[1, 3, 6, 10], [5, 11, 18, 27], [10, 13, 17, 22]], &device);
        assert_equal(rt::cumulative_sum(&a2, 1), &expected, None);
    }

    #[test]
    fn test_cumprod_basic() {
        // numpy: v2.5.2 | numpy/lib/tests/test_function_base.py::TestCumprod::test_basic (L792)
        crate::specify_test!("test_cumprod_basic");
        let mut device = TESTCFG.device.clone();
        device.set_default_order(RowMajor);

        // a = np.array([1, 2, 10, 11, 6, 5, 4])     (dtype loop N/A: rstsr checks dtypes at compile
        // time) assert_array_equal(cumprod(a, axis=-1), np.array([1, 2, 20, 220, 1320,
        // 6600, 26400]))
        let a = rt::tensor_from_nested!([1, 2, 10, 11, 6, 5, 4], &device);
        let expected = rt::tensor_from_nested!([1, 2, 20, 220, 1320, 6600, 26400], &device);
        assert_equal(rt::cumulative_prod(&a, -1), &expected, None);

        // a2 = np.array([[1, 2, 3, 4], [5, 6, 7, 9], [10, 3, 4, 5]])
        // assert_array_equal(cumprod(a2, axis=0), [[1, 2, 3, 4], [5, 12, 21, 36], [50, 36, 84,
        // 180]])
        let a2 = rt::tensor_from_nested!([[1, 2, 3, 4], [5, 6, 7, 9], [10, 3, 4, 5]], &device);
        let expected = rt::tensor_from_nested!([[1, 2, 3, 4], [5, 12, 21, 36], [50, 36, 84, 180]], &device);
        assert_equal(rt::cumulative_prod(&a2, 0), &expected, None);

        // assert_array_equal(cumprod(a2, axis=-1), [[1, 2, 6, 24], [5, 30, 210, 1890], [10, 30,
        // 120, 600]])
        let expected = rt::tensor_from_nested!([[1, 2, 6, 24], [5, 30, 210, 1890], [10, 30, 120, 600]], &device);
        assert_equal(rt::cumulative_prod(&a2, -1), &expected, None);
    }

    #[test]
    fn test_cumulative_include_initial() {
        // numpy: v2.5.2 | numpy/lib/tests/test_function_base.py::test_cumulative_include_initial
        // (L818)
        crate::specify_test!("test_cumulative_include_initial");
        let mut device = TESTCFG.device.clone();
        device.set_default_order(RowMajor);

        // arr = np.arange(8).reshape((2, 2, 2))
        // expected = [[[0, 0], [0, 1], [2, 4]], [[0, 0], [4, 5], [10, 12]]]
        // assert_array_equal(np.cumulative_sum(arr, axis=1, include_initial=True), expected)
        let arr = rt::arange((8, &device)).into_shape([2, 2, 2]);
        let expected = rt::tensor_from_nested!([[[0, 0], [0, 1], [2, 4]], [[0, 0], [4, 5], [10, 12]]], &device);
        assert_equal(rt::cumulative_sum(&arr, (1, true)), &expected, None);

        // expected = [[[1, 0, 0], [1, 2, 6]], [[1, 4, 20], [1, 6, 42]]]
        // assert_array_equal(np.cumulative_prod(arr, axis=2, include_initial=True), expected)
        let expected = rt::tensor_from_nested!([[[1, 0, 0], [1, 2, 6]], [[1, 4, 20], [1, 6, 42]]], &device);
        assert_equal(rt::cumulative_prod(&arr, (2, true)), &expected, None);

        // expected = np.array([1, 2, 4])
        // assert_array_equal(np.cumulative_prod(np.array([2, 2]), include_initial=True), expected)
        // (the `out=` cases are N/A: rstsr has no out parameter)
        let a = rt::tensor_from_nested!([2, 2], &device);
        let expected = rt::tensor_from_nested!([1, 2, 4], &device);
        assert_equal(rt::cumulative_prod(&a, true), &expected, None);
    }
}

// rstsr-specific behaviors: args spellings, strided/broadcast inputs, explicit
// output dtype, zero-size axes, and the axis=None contract.
mod custom_cumulative {
    use super::*;
    static FUNC: &str = "custom_cumulative";

    #[test]
    fn test_args_overloads() {
        crate::specify_test!("test_args_overloads");
        let mut device = TESTCFG.device.clone();
        device.set_default_order(RowMajor);

        let a = rt::tensor_from_nested!([1, 2, 3, 4], &device);
        // all spellings scan along the only axis of a 1-D input
        assert_equal(rt::cumulative_sum(&a, ()), rt::cumulative_sum(&a, 0_i32), None);
        assert_equal(rt::cumulative_sum(&a, None), rt::cumulative_sum(&a, Some(-1_isize)), None);
        assert_equal(
            rt::cumulative_sum(&a, CumulativeArgs { axis: Some(0), include_initial: false }),
            rt::cumulative_sum(&a, ()),
            None,
        );
        // bool shorthand is include_initial, not axis
        assert_equal(rt::cumulative_sum(&a, true), rt::cumulative_sum(&a, (0, true)), None);
        assert_eq!(rt::cumulative_sum(&a, true).to_vec(), vec![0, 1, 3, 6, 10]);
    }

    #[test]
    fn test_axis_none_contract() {
        crate::specify_test!("test_axis_none_contract");
        let mut device = TESTCFG.device.clone();
        device.set_default_order(RowMajor);

        // axis=None is only valid for 1-D input (np.cumsum would flatten; see
        // numpy_differences.md); 0-D input is rejected
        let a2 = rt::tensor_from_nested!([[1, 2], [3, 4]], &device);
        assert!(rt::cumulative_sum_f(&a2, None).is_err());
        assert!(rt::cumulative_prod_f(&a2, None).is_err());
        let a1 = rt::tensor_from_nested!([1, 2, 3], &device);
        assert!(rt::cumulative_sum_f(&a1, None).is_ok());
        let a0 = rt::tensor_from_nested!([7], &device).into_shape([0_usize; 0]);
        assert!(rt::cumulative_sum_f(&a0, ()).is_err());
    }

    #[test]
    fn test_strided_transposed() {
        crate::specify_test!("test_strided_transposed");
        let mut device = TESTCFG.device.clone();
        device.set_default_order(RowMajor);

        // scan along axis 0 of a transposed view (non-contiguous scan lines)
        let a = rt::tensor_from_nested!([[1, 2, 3], [4, 5, 6]], &device);
        let t = a.transpose(None);
        // t = [[1, 4], [2, 5], [3, 6]]
        let expected = rt::tensor_from_nested!([[1, 4], [3, 9], [6, 15]], &device);
        assert_equal(rt::cumulative_sum(&t, 0), &expected, None);
    }

    #[test]
    fn test_broadcast_input() {
        crate::specify_test!("test_broadcast_input");
        let mut device = TESTCFG.device.clone();
        device.set_default_order(RowMajor);

        // scan along a stride-0 (broadcast) axis: each line reads one element repeatedly
        let av = rt::tensor_from_nested!([[1], [2], [3]], &device).into_dyn();
        let b = rt::broadcast_to(&av, vec![3, 2]);
        let expected = rt::tensor_from_nested!([[1, 2], [2, 4], [3, 6]], &device);
        assert_equal(rt::cumulative_sum(&b, -1), &expected, None);
    }

    #[test]
    fn test_with_dtype() {
        crate::specify_test!("test_with_dtype");
        let mut device = TESTCFG.device.clone();
        device.set_default_order(RowMajor);

        // anti-overflow: accumulate u8 input in u64 (NumPy would widen automatically)
        let a: Tensor<u8, _> = rt::tensor_from_nested!([200, 100], &device);
        let r = a.cumulative_sum_with_dtype::<u64>(());
        assert_eq!(r.to_vec(), vec![200_u64, 300]);
        let r = a.cumulative_prod_with_dtype::<u64>(());
        assert_eq!(r.to_vec(), vec![200_u64, 20000]);
        // cast happens inside the scan: f64 accumulation of integer input
        let b = rt::tensor_from_nested!([1, 2, 3], &device);
        let r = b.cumulative_sum_with_dtype::<f64>(());
        assert_equal(&r, &rt::tensor_from_nested!([1.0, 3.0, 6.0], &device), None);
        // method spelling
        let r = b.cumulative_sum_with_dtype::<i64>(0);
        assert_eq!(r.to_vec(), vec![1_i64, 3, 6]);
    }

    #[test]
    fn test_zero_size() {
        crate::specify_test!("test_zero_size");
        let mut device = TESTCFG.device.clone();
        device.set_default_order(RowMajor);

        // empty scan axis stays empty
        let e: Tensor<f64, _> = rt::zeros(([2, 0, 3], &device));
        let r = rt::cumulative_sum(&e, 1);
        assert_eq!(r.shape().to_vec(), vec![2, 0, 3]);
        // include_initial materializes the initial value alone
        let r = rt::cumulative_sum(&e, (1, true));
        assert_eq!(r.shape().to_vec(), vec![2, 1, 3]);
        let expected: Tensor<f64, _> = rt::zeros(([2, 1, 3], &device));
        assert_equal(&r, &expected, None);
        let r = rt::cumulative_prod(&e, (1, true));
        let expected: Tensor<f64, _> = rt::ones(([2, 1, 3], &device));
        assert_equal(&r, &expected, None);
    }

    #[test]
    fn test_negative_axis_and_methods() {
        crate::specify_test!("test_negative_axis_and_methods");
        let mut device = TESTCFG.device.clone();
        device.set_default_order(RowMajor);

        let a = rt::tensor_from_nested!([[1, 2, 3], [4, 5, 6]], &device);
        assert_equal(rt::cumulative_sum(&a, -1), rt::cumulative_sum(&a, 1), None);
        // method forms on TensorAny
        let r = a.cumulative_sum((0, true));
        assert_eq!(r.shape().to_vec(), vec![3, 3]);
        assert_eq!(r[[2, 2]], 9);
        let r = a.cumulative_prod_f((0, true)).unwrap();
        assert_eq!(r[[2, 2]], 18);
    }
}
